// 多國語系(唯一來源)。零依賴,層級同 config.js/utils.js,不 import 任何模組。
// 支援 12 種語言:zh-Hant(繁中)/zh-Hans(簡中)/en(英文)/ja(日文)/fr(法文)/
// de(德文)/it(義大利文)/pt(葡萄牙文,巴西用字)/es(西班牙文,拉美/西班牙共用
// 一份翻譯)/ko(韓文)/id(印尼文)/hi(印地文)。
// 語言判別:navigator.languages 逐一比對前綴(zh*/ja*/en*/fr*/de*/it*/pt*/es*/ko*/id*/hi*),
// 全部不符則預設英文。zh* 再依 region/script 細分繁簡:zh-Hans/zh-CN/zh-SG/zh-MY
// 走簡體,其餘(含只寫 zh 的)走繁體。localStorage 的 gv-lang(值為上述語言代碼之一)可覆寫自動判別——
// 設定 → 偏好設定 → 介面語言 有下拉選單可手動切換。
// 用法:t("key") 取字串、t("key", {n: 3}) 帶參數({n} 佔位替換);
// index.html 的靜態文字用 data-i18n / data-i18n-ph / data-i18n-title 屬性,
// 由 applyI18n()(app.js 開機時呼叫一次)套用。
// 後端 AI 生成的固定 prompt(app/routers/ai.py 的 PROMPTS)也支援同一組語言代碼,
// api.js 呼叫時帶上 aiLang()——預設跟隨 LANG,可被 localStorage 的 gv-ai-lang 覆寫
// (設定 → 偏好設定 → AI 生成語言),讓介面語言與生成內容語言可以分開設定。

