    "admin.bkListTitle": "備份紀錄",
    "admin.bkHint": "整站備份:所有使用者的名詞、附件、回收桶與各自的設定,加上帳號登記簿與站台設定。可重建的搜尋索引與語意向量不含在內(還原後自動重建)。這與「匯出/入」不同——那是把自己的庫搬到另一台,這是同一台的災難復原。 介面語言、字級、Logo/標語文字、圖片壓縮開關等偏好存在瀏覽器本機(localStorage),不在伺服器的資料目錄裡,因此不含在備份中——換一台電腦或清除瀏覽器資料就要重設。",
