    "plugin.comingSoon": "此分類的外掛尚未開放安裝,敬請期待",
    "plugin.enhancesLabel": "強化對象:{name}",
    "plugin.upload": "上傳外掛封裝(.zip)…",
    "plugin.guideTitle": "想自己做一個外掛?(不用會寫程式)",
    "plugin.guideDiyHint": "「欄位樣板」類的外掛做起來相對容易:它是純資料、沒有任何程式碼——一個 plugin.json 描述欄位長什麼樣,打包成 zip 就能上傳測試。裝壞了解除安裝即可,名詞的資料不會受影響。歡迎自己做一個試試,也歡迎發 PR 讓它變成官方封裝。",
    "plugin.guideStep1": "先在畫面上把欄位樣板調到你要的樣子",
    "plugin.guideStep1Desc": "到 內容 → 欄位樣板,把欄位、標題、提示文字、AI 指示都調好,再按「匯出樣板」。你會拿到一個 .json 檔——裡面那段就是等一下要用的東西,不必手打。",
    "plugin.guideStep2": "建一個資料夾,裡面放一個 plugin.json",
    "plugin.guideStep2Desc": "資料夾名字就是外掛 id(例如 coffee-note)。用記事本把下面這段複製進 plugin.json,把 id、名稱、說明改成你的,再把剛剛匯出的樣板那段貼到 template 裡。",
    "plugin.guideStep3": "壓成 .zip,在下面按「上傳外掛封裝」試裝",
    "plugin.guideStep3Desc": "在資料夾上按右鍵壓縮就好。上傳後它會出現在上方的型錄裡,按安裝就能用。哪裡寫錯了會直接告訴你原因(例如少了必填的英文名稱),照著改再傳一次即可。需要站台管理者權限。",
    "plugin.guideStep4": "分享到 GitHub,讓別人也裝得到",
    "plugin.guideStep4Desc": "最簡單的方式:在 GitHub 網頁上按 Fork 複製本專案,把你的資料夾放進 official_plugins/,再按 Create pull request。全程在瀏覽器點一點就好,不用裝任何工具。被收錄後,所有人更新版本就自動有你的外掛。或者你也可以自己開一個 repo,把 .zip 放在 Releases 讓人下載。",
    "plugin.guideCopy": "複製",
    "plugin.guideCopied": "已複製",
    "plugin.guideSamples": "看官方外掛的寫法",
    "plugin.guidePr": "到 GitHub 送出你的外掛",
    "plugin.guideRules": "三個最常卡住的地方:① 資料夾名稱要跟 plugin.json 裡的 id 一模一樣;② name 一定要有 en 這個英文名稱(其他語言沒寫的人會看到它);③ 欄位的 key 只能用小寫英文、數字和底線,而且要用英文字母開頭(顯示給人看的是 label,key 只是內部代號)。",
