    "srs.helpWhat": "遮住说明只看名词,先自己回想,再翻牌对答案。回想这个动作本身就会让记忆变牢——比重读一遍有效得多。答对了就把下次复习往后推,答错就拉回来。",
    "srs.helpBoxesT": "盒序:1 → 3 → 7 → 14 → 30 → 90 天",
    "srs.helpBoxes": "每条名词待在一个“盒子”里,盒子决定多久后再见到它。按“记得”就往下一个盒子走,间隔拉长;按“忘了”就退回第一盒,明天再来。只有两个选项,不用纠结自己记得几分。",
    "srs.helpZeroT": "零负债:一轮 {n} 张,抽完就结束",
    "srs.helpZero": "这里不会出现“今天还有 N 张到期”。没复习的日子不会累积成待办,也不会有红色数字追着你。想复习就打开抽一轮,{n} 张抽完就结束——这个库是给你在职场上遇到行话时用的,不是考前冲刺用的。",
    "srs.helpScopeT": "范围:日期区间 + 标签分类 + 标签群组 可以一起用",
    "srs.helpScope": "抽卡抽的是“侧栏现在圈出来的东西”。拖上面那条日期轨道,就只复习那段时间内的名词——上周开会记的一批、上个月刚接手的项目,都可以单独拿出来复习;旁边的切换钮还能把时间轴换成创建时间。同时点左边的“标签分类”与“标签群组”可以再缩小范围,三者是叠加的。弹窗顶端会把实际生效的范围列出来,想复习全部就按那里的“改用全库”。",
