    "admin.bkHint": "整站备份:所有用户的名词、附件、回收站与各自的设置,加上账号登记簿与站点设置。可重建的搜索索引与语义向量不含在内(还原后自动重建)。这与「导出/入」不同——那是把自己的库搬到另一台,这是同一台的灾难恢复。 界面语言、字级、Logo/标语文字、图片压缩开关等偏好存在浏览器本机(localStorage),不在服务器的数据目录里,因此不含在备份中——换一台电脑或清除浏览器数据就要重设。",
