    "plugin.guideStep2Desc": "文件夹名字就是插件 id(例如 coffee-note)。用记事本把下面这段复制进 plugin.json,把 id、名称、说明改成你的,再把刚刚导出的模板那段粘贴到 template 里。",
    "plugin.guideStep3": "压成 .zip,在下面按“上传插件封装”试装",
    "plugin.guideStep3Desc": "在文件夹上右键压缩就好。上传后它会出现在上方的目录里,按安装就能用。哪里写错了会直接告诉你原因(例如少了必填的英文名称),照着改再传一次即可。需要站台管理员权限。",
    "plugin.guideStep4": "分享到 GitHub,让别人也装得到",
    "plugin.guideStep4Desc": "最简单的方式:在 GitHub 网页上按 Fork 复制本项目,把你的文件夹放进 official_plugins/,再按 Create pull request。全程在浏览器点一点就好,不用装任何工具。被收录后,所有人更新版本就自动有你的插件。或者你也可以自己开一个 repo,把 .zip 放在 Releases 让人下载。",
    "plugin.guideCopy": "复制",
    "plugin.guideCopied": "已复制",
    "plugin.guideSamples": "看官方插件的写法",
    "plugin.guidePr": "到 GitHub 提交你的插件",
    "plugin.guideRules": "三个最常卡住的地方:① 文件夹名称要跟 plugin.json 里的 id 一模一样;② name 一定要有 en 这个英文名称(其他语言没写的人会看到它);③ 字段的 key 只能用小写英文、数字和下划线,而且要用英文字母开头(显示给人看的是 label,key 只是内部代号)。",
