    "srs.open": "Review",
    "srs.openTitle": "Draw review cards from the current filter scope",
    "srs.helpTitle": "What is this?",
    "srs.helpHeading": "How review works",
    "srs.helpWhatT": "Spaced repetition: review right before you forget",
    "srs.helpWhat": "The description is hidden and you see only the term. Try to recall it, then flip the card to check. The act of retrieving is what makes it stick — far more than re-reading. Get it right and the next review moves further out; get it wrong and it comes back sooner.",
    "srs.helpBoxesT": "Boxes: 1 → 3 → 7 → 14 → 30 → 90 days",
    "srs.helpBoxes": "Each term sits in a box, and the box decides how long until you see it again. “Remembered” moves it to the next box and stretches the gap; “Forgot” sends it back to the first box for tomorrow. Only two choices — no agonising over how well you remembered.",
    "srs.helpZeroT": "No debt: {n} cards a round, then you're done",
    "srs.helpZero": "You will never see “N cards due today”. Days you skip don't pile up into a backlog, and no red number chases you. Open it when you feel like it, draw a round, and after {n} cards you're finished — this vault is for the jargon you meet at work, not for cramming before an exam.",
    "srs.helpScopeT": "Scope: date range + template + tag group, combined",
    "srs.helpScope": "A round is drawn from whatever the sidebar currently selects. Drag the date track above and you review only the terms from that stretch of time — the batch you took down in last week's meeting, or the project you picked up last month. The toggle beside it switches the timeline to creation time. Pick a template under “Templates” and a group under “Tag groups” to narrow further; all three stack. The popup lists the scope actually in effect, and has a “use whole vault” switch when you want everything.",
