    "admin.publicShareHint": "Off by default. Once enabled, users can create public links to their own notes; links are revocable at any time and every response is marked noindex so it never lands in a search engine. Turning this off kills all existing links immediately.",
    "admin.save": "Save",
    "admin.rlTitle": "Login protection",
    "admin.rlEnable": "Lock out after repeated login failures",
    "admin.rlHint": "Once failures within the window reach the threshold, logins are temporarily locked — including the correct password (otherwise guessing it right would sail straight through). The two dimensions are independent: per-IP stops one machine spraying many accounts, per-account stops many machines spraying one account.",
    "admin.rlIpMax": "Max per IP",
    "admin.rlEmailMax": "Max per account",
