    "admin.rlLockout": "Lockout (min)",
    "admin.rlTrustXff": "Trust the X-Forwarded-For header (only when behind a reverse proxy / Cloudflare Tunnel)",
    "admin.rlXffHint": "Both directions bite. Behind a proxy with this off, every request looks like the proxy's single address, so a few failures lock out everyone. With no proxy and this on, the header is whatever the client says it is, and an attacker rotates fake addresses to sidestep the per-IP limit entirely (per-account still applies).",
    "admin.rlReset": "Clear all lockouts now",
    "admin.rlResetDone": "All lockouts cleared",
    "admin.bkTitle": "Backup and restore",
    "admin.bkListTitle": "Backup history",
    "admin.bkHint": "Whole-site backup: every user's entries, attachments, trash and settings, plus the account registry and site settings. The rebuildable search index and semantic vectors are not included (they are rebuilt after a restore). This is not the same as Import/Export — that moves your own library to another site, this is disaster recovery for this one. Preferences such as interface language, font size, logo/tagline text and the image-compression switch live in the browser (localStorage), not in the server's data directory, so they are not part of a backup — you will set them again on a new machine or after clearing browser data.",
    "admin.bkAuto": "Enable automatic backups",
