    "admin.bkKeep": "Keep N copies",
    "admin.bkAtTime": "Backup time",
    "admin.bkAtTimeHint": "Leave the time blank to back up as soon as the interval is up. If set, it means \"not before\" that time: once due, the backup runs the first time someone opens the site after that hour (there is deliberately no resident scheduler). If nobody opens it that day, it rolls over to the next visit.",
