    "plugin.enhancesLabel": "Enhances: {name}",
    "plugin.upload": "Upload plugin package (.zip)…",
    "plugin.guideTitle": "Want to build your own plugin? (no coding needed)",
    "plugin.guideDiyHint": "Field-template plugins are the easy kind: pure data with no code at all — one plugin.json describing the fields, zipped up and uploaded. If it turns out wrong just uninstall it; your notes are untouched. Try building one, and send a PR if you want it shipped as an official package.",
    "plugin.guideStep1": "First, build the field template you want in the UI",
    "plugin.guideStep1Desc": "Go to Content → Field templates, set up the fields, labels, placeholders and AI prompt, then hit “Export templates”. You get a .json file — that block is exactly what you need next, no typing required.",
    "plugin.guideStep2": "Make a folder with one plugin.json inside",
    "plugin.guideStep2Desc": "The folder name is the plugin id (e.g. coffee-note). Copy the block below into plugin.json with any text editor, change the id, name and description to yours, then paste the template you just exported into “template”.",
    "plugin.guideStep3": "Zip it up and try it with “Upload plugin package” below",
    "plugin.guideStep3Desc": "Right-click the folder and compress it. After uploading it shows up in the catalog above — click Install and it's live. If something is wrong you get the exact reason (e.g. the required English name is missing); fix it and upload again. Requires site admin rights.",
    "plugin.guideStep4": "Share it on GitHub so others can install it",
    "plugin.guideStep4Desc": "The easiest route: on the GitHub website click Fork, drop your folder into official_plugins/, then click Create pull request. It's all point-and-click in the browser — no tools to install. Once merged, everyone gets your plugin on their next update. You can also just publish the .zip in your own repo's Releases.",
    "plugin.guideCopy": "Copy",
    "plugin.guideCopied": "Copied",
    "plugin.guideSamples": "Browse official plugins",
    "plugin.guidePr": "Submit yours on GitHub",
    "plugin.guideRules": "The three things people trip on: ① the folder name must match the id in plugin.json exactly; ② name must include an “en” entry (it's the fallback everyone sees when their language is missing); ③ a field key may only use lowercase letters, digits and underscores, and must start with a letter (what people see is the label — the key is just an internal name).",
    "plugin.uploadOk": "Package uploaded — plugin added to the catalog",
    "plugin.uploadFail": "Upload failed",
    "plugin.scanErrTitle": "These packages failed validation and were not added to the catalog (admins only):",
