    "admin.bkHint": "サイト全体のバックアップ:全ユーザーの用語・添付・ごみ箱・各自の設定に加え、アカウント台帳とサイト設定。再構築できる検索インデックスと意味ベクトルは含みません(復元後に自動で再構築します)。「エクスポート/インポート」とは別物です——あちらは自分のライブラリを別のサイトへ移すもの、これはこのサイトの災害復旧です。 インターフェース言語、文字サイズ、ロゴ/タグラインの文字、画像圧縮のスイッチなどの設定はブラウザ側(localStorage)に保存され、サーバーのデータディレクトリにはありません。したがってバックアップには含まれません——別の端末やブラウザデータ消去後は設定し直しになります。",
