    "plugin.guideTitle": "自分でプラグインを作ってみますか?(プログラミング不要)",
    "plugin.guideDiyHint": "「フィールドテンプレート」系のプラグインは比較的簡単です:コードは一切なく、純粋なデータだけ——フィールドを記述した plugin.json を zip にまとめてアップロードするだけです。うまくいかなければアンインストールすれば済み、用語のデータには影響しません。ぜひ作ってみてください。PR を送れば公式パッケージにもなります。",
    "plugin.guideStep1": "まず画面上で項目テンプレートを好みの形に整える",
    "plugin.guideStep1Desc": "コンテンツ → 項目テンプレートで、項目・ラベル・プレースホルダー・AI 指示を整えてから「テンプレートを書き出す」を押します。得られる .json の中身が次の手順でそのまま使えます。手入力は不要です。",
    "plugin.guideStep2": "フォルダーを 1 つ作り、中に plugin.json を置く",
    "plugin.guideStep2Desc": "フォルダー名がプラグイン id です(例:coffee-note)。下のブロックをテキストエディターで plugin.json にコピーし、id・名前・説明を自分のものに変え、さきほど書き出したテンプレートを template に貼り付けます。",
    "plugin.guideStep3": "zip に圧縮し、下の「パッケージをアップロード」で試す",
    "plugin.guideStep3Desc": "フォルダーを右クリックして圧縮するだけです。アップロードすると上のカタログに現れ、インストールを押せば使えます。不備があれば理由がそのまま表示されます(例:必須の英語名がない)。直して再アップロードしてください。サイト管理者権限が必要です。",
    "plugin.guideStep4": "GitHub で共有して、ほかの人も入れられるようにする",
    "plugin.guideStep4Desc": "いちばん簡単なのは、GitHub のサイトで Fork を押し、自分のフォルダーを official_plugins/ に入れて Create pull request を押す方法です。すべてブラウザー上のクリックだけで、ツールのインストールは不要です。取り込まれれば、次の更新でみんなの環境に入ります。自分のリポジトリの Releases に .zip を置いて配る方法もあります。",
    "plugin.guideCopy": "コピー",
