    "plugin.guideRules": "つまずきやすい 3 点:① フォルダー名は plugin.json の id と完全に一致させる、② name には必ず「en」を入れる(その言語がない人にはこれが表示される)、③ 項目の key は小文字英字・数字・アンダースコアのみで、英字で始める(表示されるのは label で、key は内部名)。",
