    "srs.open": "Réviser",
    "srs.openTitle": "Tirer des cartes de révision dans la sélection actuelle",
    "srs.helpTitle": "Qu'est-ce que c'est ?",
    "srs.helpHeading": "Comment fonctionne la révision",
    "srs.helpWhatT": "Répétition espacée : réviser juste avant d'oublier",
    "srs.helpWhat": "La description est masquée, vous ne voyez que le terme. Essayez de vous en souvenir, puis retournez la carte pour vérifier. C'est l'effort de rappel qui ancre la mémoire — bien plus que relire. Si c'est juste, la prochaine révision s'éloigne ; sinon, elle revient plus tôt.",
    "srs.helpBoxesT": "Boîtes : 1 → 3 → 7 → 14 → 30 → 90 jours",
    "srs.helpBoxes": "Chaque terme occupe une boîte, et la boîte détermine le délai avant de le revoir. « Je m'en souvenais » le fait passer à la boîte suivante et allonge l'intervalle ; « J'ai oublié » le renvoie à la première boîte, pour demain. Deux choix seulement — pas besoin de noter finement votre souvenir.",
    "srs.helpZeroT": "Zéro dette : {n} cartes par tour, et c'est fini",
    "srs.helpZero": "Vous ne verrez jamais « N cartes à réviser aujourd'hui ». Les jours sautés ne s'accumulent pas en retard, et aucun chiffre rouge ne vous poursuit. Ouvrez quand vous voulez, tirez un tour, et après {n} cartes c'est terminé — ce coffre sert au jargon rencontré au travail, pas au bachotage.",
    "srs.helpScopeT": "Portée : plage de dates + modèle + groupe de mots-clés, combinables",
    "srs.helpScope": "Un tour est tiré de ce que la barre latérale sélectionne actuellement. Faites glisser la piste de dates ci-dessus et vous ne révisez que les termes de cette période — ceux notés en réunion la semaine dernière, ou le projet repris le mois dernier. Le bouton à côté bascule l'axe temporel sur la date de création. Choisissez un modèle sous « Modèles » et un groupe sous « Groupes de mots-clés » pour affiner ; les trois se cumulent. La fenêtre indique la portée réellement appliquée et propose « tout le coffre » si vous voulez tout.",
    "srs.helpClose": "Compris",
