    "admin.publicShareHint": "Désactivé par défaut. Une fois activé, les utilisateurs peuvent créer des liens publics vers leurs propres notes ; les liens sont révocables à tout moment et chaque réponse est marquée noindex pour ne jamais apparaître dans un moteur de recherche. Désactiver cette option invalide immédiatement tous les liens existants.",
