    "admin.rlTitle": "Protection de la connexion",
    "admin.rlEnable": "Verrouiller après des échecs de connexion répétés",
    "admin.rlHint": "Dès que les échecs dans la fenêtre atteignent le seuil, la connexion est temporairement verrouillée — même avec le bon mot de passe (sinon le deviner suffirait à passer). Les deux axes sont indépendants : par IP contre « une machine qui arrose beaucoup de comptes », par compte contre « beaucoup de machines sur un seul compte ».",
    "admin.rlIpMax": "Max par IP",
    "admin.rlEmailMax": "Max par compte",
    "admin.rlWindow": "Fenêtre de comptage (min)",
    "admin.rlLockout": "Verrouillage (min)",
    "admin.rlTrustXff": "Faire confiance à l'en-tête X-Forwarded-For (uniquement derrière un proxy inverse / Cloudflare Tunnel)",
    "admin.rlXffHint": "Les deux sens posent problème. Derrière un proxy avec l'option désactivée, tout le monde partage l'adresse du proxy : quelques échecs verrouillent tout le monde. Sans proxy avec l'option activée, l'en-tête est ce que le client veut bien écrire, et un attaquant change d'adresse factice à chaque essai pour contourner la limite par IP (celle par compte reste active).",
    "admin.rlReset": "Lever tous les verrouillages",
    "admin.rlResetDone": "Tous les verrouillages ont été levés",
    "admin.bkTitle": "Sauvegarde et restauration",
    "admin.bkListTitle": "Historique des sauvegardes",
    "admin.bkHint": "Sauvegarde de tout le site : les entrées, pièces jointes, corbeille et réglages de chaque utilisateur, plus le registre des comptes et les réglages du site. L'index de recherche et les vecteurs sémantiques, reconstructibles, ne sont pas inclus (ils sont recréés après une restauration). À ne pas confondre avec Import/Export : celui-ci déplace votre bibliothèque vers un autre site, ceci est la reprise après sinistre de celui-ci. Les préférences comme la langue de l'interface, la taille du texte, le logo/slogan et l'option de compression d'images sont stockées dans le navigateur (localStorage), pas dans le répertoire de données du serveur : elles ne font donc pas partie d'une sauvegarde — il faudra les régler à nouveau sur une autre machine ou après effacement des données du navigateur.",
    "admin.bkAuto": "Activer les sauvegardes automatiques",
    "admin.bkInterval": "Tous les N jours",
    "admin.bkKeep": "Conserver N copies",
    "admin.bkAtTime": "Heure de sauvegarde",
    "admin.bkAtTimeHint": "Laissez l'heure vide pour sauvegarder dès l'échéance. Si vous la renseignez, elle signifie « pas avant » : une fois l'échéance atteinte, la sauvegarde se lance à la première ouverture du site après cette heure (il n'y a volontairement pas de planificateur résident). Si personne n'ouvre le site ce jour-là, elle est reportée.",
    "admin.bkLast": "Dernière sauvegarde automatique : {when}",
    "admin.bkNever": "Aucune sauvegarde automatique",
    "admin.bkNow": "Sauvegarder maintenant",
    "admin.bkUpload": "Téléverser une sauvegarde…",
