    "admin.bkDownload": "Télécharger",
    "admin.bkRestore": "Restaurer",
    "admin.bkDelete": "Supprimer",
    "admin.bkDeleteConfirm": "Supprimer cette sauvegarde ? Action irréversible.",
    "admin.bkRestoreConfirm": "Restauration de tout le site depuis « {name} ».\n\nCette archive contient {n} utilisateurs ; réglages du site : {settings}.\n\nLes données actuelles seront entièrement remplacées — les entrées et comptes créés après cette sauvegarde disparaîtront. Un instantané de pré-restauration est enregistré automatiquement.",
