    "plugin.uninstallTplConfirm": "Désinstaller « {name} » ? Son modèle est retiré de la liste des modèles de champs ; les notes existantes et leurs valeurs restent intactes, et la réinstallation restaure le modèle par défaut.",
    "plugin.uninstallInUse": "⚠ {n} termes utilisent actuellement ce modèle : après désinstallation, leurs libellés de champs deviendront des clés brutes (aucune donnée n'est perdue). Le contrôle de santé du contenu les liste et peut tout rebasculer vers le modèle par défaut en un clic.",
