    "plugin.comingSoon": "Les extensions de cette catégorie ne peuvent pas encore être installées — bientôt disponible",
    "plugin.enhancesLabel": "Améliore : {name}",
    "plugin.upload": "Téléverser un paquet d'extension (.zip)…",
    "plugin.guideTitle": "Envie de créer votre propre extension ? (sans coder)",
    "plugin.guideDiyHint": "Les extensions de type « modèle de champs » sont les plus faciles : des données pures, sans aucun code — un seul plugin.json décrivant les champs, compressé en zip et téléversé. Si le résultat ne convient pas, désinstallez : vos notes ne changent pas. Essayez d'en créer une, et proposez une PR pour qu'elle devienne officielle.",
    "plugin.guideStep1": "D'abord, composez le modèle de champs voulu dans l'interface",
    "plugin.guideStep1Desc": "Allez dans Contenu → Modèles de champs, réglez les champs, libellés, textes d'aide et l'instruction IA, puis cliquez sur « Exporter les modèles ». Vous obtenez un .json — ce bloc est exactement ce qu'il vous faut ensuite, rien à taper.",
    "plugin.guideStep2": "Créez un dossier contenant un plugin.json",
    "plugin.guideStep2Desc": "Le nom du dossier est l'id de l'extension (ex. coffee-note). Copiez le bloc ci-dessous dans plugin.json avec un éditeur de texte, changez l'id, le nom et la description, puis collez le modèle que vous venez d'exporter dans « template ».",
    "plugin.guideStep3": "Compressez en .zip et testez avec « Téléverser un paquet » ci-dessous",
    "plugin.guideStep3Desc": "Clic droit sur le dossier pour le compresser. Après le téléversement, il apparaît dans le catalogue ci-dessus : cliquez sur Installer et c'est prêt. En cas d'erreur, la raison exacte s'affiche (ex. le nom anglais obligatoire manque) ; corrigez et renvoyez. Droits d'administrateur du site requis.",
    "plugin.guideStep4": "Partagez-la sur GitHub pour que d'autres l'installent",
    "plugin.guideStep4Desc": "Le plus simple : sur le site GitHub, cliquez sur Fork, déposez votre dossier dans official_plugins/, puis cliquez sur Create pull request. Tout se fait à la souris dans le navigateur, aucun outil à installer. Une fois fusionnée, votre extension arrive chez tout le monde à la mise à jour suivante. Vous pouvez aussi publier le .zip dans les Releases de votre propre dépôt.",
    "plugin.guideCopy": "Copier",
    "plugin.guideCopied": "Copié",
    "plugin.guideSamples": "Voir les extensions officielles",
    "plugin.guidePr": "Soumettre la vôtre sur GitHub",
    "plugin.guideRules": "Les trois pièges classiques : ① le nom du dossier doit correspondre exactement à l'id dans plugin.json ; ② name doit contenir une entrée « en » (c'est le repli affiché quand la langue manque) ; ③ une clé de champ n'accepte que minuscules, chiffres et tirets bas, et doit commencer par une lettre (ce qui s'affiche, c'est le label — la clé est un nom interne).",
    "plugin.uploadOk": "Paquet téléversé — extension ajoutée au catalogue",
    "plugin.uploadFail": "Échec du téléversement",
    "plugin.scanErrTitle": "Ces paquets ont échoué à la validation et n'ont pas été ajoutés au catalogue (visibles par les administrateurs uniquement) :",
