    "tplmgr.aiPromptLangHint": "Cette consigne est en anglais à dessein : les petits modèles locaux suivent mieux les instructions en anglais. Elle ne détermine pas la langue du contenu généré — cela vient de Préférences → Langue de génération IA. Vous pouvez la réécrire dans votre langue.",
    "tplmgr.aiPromptPh": "Consignes de contenu pour l'IA…",
    "tplmgr.builtinHint": "Les noms des modèles intégrés s'affichent dans la langue de l'interface tant qu'ils restent par défaut ; renommez-en un et votre nom personnalisé sera utilisé à la place. Les libellés de champs et la consigne IA sont modifiables ; les clés des champs existants sont verrouillées, mais les champs que vous ajoutez peuvent avoir leur propre clé. « Mot anglais » et « Extrait de code » sont désactivés par défaut — activez-les depuis la liste ci-dessus. Les noms et astuces des champs suivent la langue de l'interface tant qu'ils ne sont pas modifiés ; une fois personnalisés, votre texte est toujours affiché.",

