    "sem.intro": "La recherche sémantique trouve les entrées par le sens : même sans vous rappeler le nom, il suffit de décrire le sujet. Réglez d'abord un modèle d'embedding dans l'onglet « Génération IA », puis créez l'index ici.",
    "sem.staleHint": "L'index n'est pas mis à jour automatiquement lors d'un ajout ou d'une modification (l'enregistrement ne doit jamais ralentir ni échouer parce que le service de modèles est arrêté). Revenez de temps en temps appuyer sur « Créer / mettre à jour l'index ».",
