    "health.title": "Bilan de santé du contenu",
    "health.desc": "Parcourt toute la bibliothèque pour repérer ce qui est déjà cassé (fichiers joints disparus, images brisées dans la description), ce qui gaspille de l'espace (fichiers trop volumineux, fichiers orphelins qu'aucune fiche ne référence) et ce qui reste à ranger (aucun mot-clé, aucune description, liens pointant vers des fiches inexistantes). Ce bilan se contente de signaler : rien n'est modifié ni supprimé automatiquement.",
