    "health.kind.empty_desc": "Aucune description",
    "health.hint.unreadable": "Ce fichier ne peut pas être analysé (YAML corrompu ou fichier tronqué) ; son contenu est actuellement illisible. Ouvrez-le dans un éditeur de texte pour l'inspecter, ou restaurez-le depuis une sauvegarde.",
    "health.hint.missing_asset": "La fiche déclare une pièce jointe, mais le fichier n'est plus sur le disque. Cela arrive généralement après une suppression manuelle, ou après la restauration d'une sauvegarde sans son dossier assets.",
    "health.hint.missing_embed": "Une image de la description pointe vers un fichier inexistant et s'affiche donc comme image brisée. Téléversez-la à nouveau, ou retirez cette image du texte.",
    "health.hint.large_asset": "Pièces jointes de plus de 2 Mo. S'il s'agit d'une image, l'outil « Compresser les images déjà jointes » ci-dessous peut s'en charger ; les gros fichiers non images ne sont qu'un signalement.",
    "health.hint.orphan_file": "Le fichier est toujours sur le disque, mais aucune fiche (versions historiques comprises) ne le référence. ⚠ Les pièces jointes d'une fiche en cours de création et non encore enregistrée apparaissent aussi ici : ne supprimez pas trop vite.",
    "health.hint.broken_link": "La fiche visée par le lien n'existe pas. Elle n'a peut-être simplement pas encore été créée (c'est permis : le lien se connectera tout seul plus tard), ou il s'agit d'un ancien lien rompu après le renommage de la cible.",
    "health.hint.missing_template": "Ces termes référencent un modèle supprimé (généralement un plugin de modèle désinstallé). Rien n'est perdu — les libellés de champs sont juste remplacés par leurs clés brutes. Réinstallez le plugin, ou utilisez le bouton ci-dessous pour tout rebasculer vers le modèle par défaut (les valeurs des champs sont conservées).",
    "health.hint.no_tags": "Les fiches sans mot-clé n'apparaissent nulle part dans l'arborescence de la barre latérale ; seule la recherche permet de les retrouver.",
    "health.hint.empty_desc": "Un terme sans la moindre explication. C'est le type de fiche que vous risquez le plus de ne plus comprendre en y revenant plus tard.",
