    "srs.open": "Wiederholen",
    "srs.openTitle": "Karten aus dem aktuellen Filterbereich ziehen",
    "srs.helpTitle": "Was ist das?",
    "srs.helpHeading": "So funktioniert das Wiederholen",
    "srs.helpWhatT": "Verteiltes Wiederholen: kurz bevor du es vergisst",
    "srs.helpWhat": "Die Beschreibung ist verdeckt, du siehst nur den Begriff. Versuche dich zu erinnern und drehe dann die Karte um. Das Abrufen selbst festigt das Gedächtnis — weit mehr als nochmaliges Lesen. Richtig: die nächste Wiederholung rückt weiter weg; falsch: sie kommt früher zurück.",
    "srs.helpBoxesT": "Fächer: 1 → 3 → 7 → 14 → 30 → 90 Tage",
    "srs.helpBoxes": "Jeder Begriff liegt in einem Fach, und das Fach bestimmt, wann er wiederkommt. „Gewusst“ schiebt ihn ins nächste Fach und verlängert den Abstand; „Vergessen“ setzt ihn zurück ins erste Fach für morgen. Nur zwei Optionen — kein Grübeln, wie gut du es wusstest.",
    "srs.helpZeroT": "Keine Schulden: {n} Karten pro Runde, dann ist Schluss",
    "srs.helpZero": "Du wirst nie „N Karten heute fällig“ sehen. Ausgelassene Tage häufen sich nicht zu einem Rückstand, und keine rote Zahl verfolgt dich. Öffne es, wann du magst, zieh eine Runde, und nach {n} Karten ist Schluss — dieser Tresor ist für Fachjargon aus dem Arbeitsalltag, nicht fürs Pauken vor einer Prüfung.",
    "srs.helpScopeT": "Umfang: Zeitraum + Vorlage + Schlagwortgruppe, kombinierbar",
    "srs.helpScope": "Eine Runde wird aus dem gezogen, was die Seitenleiste gerade auswählt. Zieh oben die Datumsleiste, und du wiederholst nur Begriffe aus diesem Zeitraum — die Charge aus dem Meeting letzte Woche oder das Projekt vom letzten Monat. Der Schalter daneben stellt die Zeitachse auf das Erstelldatum um. Mit einer Vorlage unter „Vorlagen“ und einer Gruppe unter „Schlagwortgruppen“ grenzt du weiter ein; alle drei greifen zusammen. Das Fenster nennt den tatsächlich geltenden Umfang und bietet „ganzer Tresor“, wenn du alles willst.",
    "srs.helpClose": "Verstanden",
