    "admin.publicShareHint": "Standardmäßig aus. Nach dem Aktivieren können Nutzende öffentliche Links zu eigenen Notizen erzeugen; Links sind jederzeit widerrufbar und jede Antwort wird mit noindex markiert, landet also nie in einer Suchmaschine. Das Deaktivieren macht alle bestehenden Links sofort ungültig.",
