    "admin.rlHint": "Erreichen die Fehlversuche im Zeitfenster den Schwellwert, wird die Anmeldung vorübergehend gesperrt — auch mit korrektem Passwort (sonst käme ein Treffer sofort durch). Die beiden Achsen sind unabhängig: pro IP gegen „eine Maschine probiert viele Konten“, pro Konto gegen „viele Maschinen probieren ein Konto“.",
