    "admin.rlTrustXff": "X-Forwarded-For-Header vertrauen (nur hinter Reverse Proxy / Cloudflare Tunnel)",
    "admin.rlXffHint": "Beide Richtungen sind gefährlich. Hinter einem Proxy und ausgeschaltet sieht jede Anfrage nach derselben Proxy-Adresse aus — wenige Fehlversuche sperren alle aus. Ohne Proxy und eingeschaltet steht im Header, was der Client hineinschreibt; ein Angreifer wechselt einfach die gefälschte Adresse und umgeht das IP-Limit vollständig (das Konto-Limit greift weiterhin).",
    "admin.rlReset": "Alle Sperren sofort aufheben",
    "admin.rlResetDone": "Alle Sperren aufgehoben",
    "admin.bkTitle": "Sicherung und Wiederherstellung",
    "admin.bkListTitle": "Sicherungsverlauf",
    "admin.bkHint": "Sicherung der gesamten Website: Einträge, Anhänge, Papierkorb und Einstellungen aller Benutzer sowie Kontoregister und Website-Einstellungen. Der wiederherstellbare Suchindex und die semantischen Vektoren sind nicht enthalten (sie werden nach dem Wiederherstellen neu aufgebaut). Nicht zu verwechseln mit Import/Export — das verschiebt die eigene Bibliothek auf eine andere Website, dies ist die Notfallwiederherstellung dieser. Einstellungen wie Oberflächensprache, Schriftgröße, Logo-/Slogan-Text und der Schalter für die Bildkomprimierung liegen im Browser (localStorage), nicht im Datenverzeichnis des Servers, und sind daher nicht Teil einer Sicherung — auf einem anderen Rechner oder nach dem Löschen der Browserdaten müssen sie neu gesetzt werden.",
    "admin.bkAuto": "Automatische Sicherungen aktivieren",
    "admin.bkInterval": "Alle N Tage",
