    "plugin.uninstallInUse": "⚠ {n} Begriffe verwenden derzeit diese Vorlage: Nach der Deinstallation erscheinen ihre Feldbeschriftungen als rohe Schlüssel (keine Daten gehen verloren). Die Inhaltsprüfung listet sie auf und kann sie mit einem Klick zur Standardvorlage verschieben.",
