    "plugin.upload": "Plugin-Paket hochladen (.zip)…",
    "plugin.guideTitle": "Eigenes Plugin bauen? (ohne Programmieren)",
    "plugin.guideDiyHint": "Plugins vom Typ „Feldvorlage“ sind die einfache Sorte: reine Daten, überhaupt kein Code — eine plugin.json beschreibt die Felder, als zip gepackt und hochgeladen. Passt es nicht, einfach deinstallieren; deine Notizen bleiben unberührt. Bau ruhig eins und schick eine PR, wenn es offiziell werden soll.",
    "plugin.guideStep1": "Zuerst die gewünschte Feldvorlage in der Oberfläche bauen",
    "plugin.guideStep1Desc": "Unter Inhalt → Feldvorlagen die Felder, Beschriftungen, Platzhalter und die KI-Anweisung einrichten, dann „Vorlagen exportieren“ klicken. Sie erhalten eine .json-Datei — genau dieser Block wird im nächsten Schritt gebraucht, nichts abtippen.",
    "plugin.guideStep2": "Einen Ordner anlegen, darin eine plugin.json",
    "plugin.guideStep2Desc": "Der Ordnername ist die Plugin-id (z. B. coffee-note). Den Block unten mit einem Texteditor in plugin.json kopieren, id, Name und Beschreibung anpassen und die eben exportierte Vorlage in „template“ einfügen.",
    "plugin.guideStep3": "Als .zip packen und unten mit „Plugin-Paket hochladen“ testen",
    "plugin.guideStep3Desc": "Ordner rechtsklicken und komprimieren. Nach dem Hochladen erscheint es oben im Katalog — auf Installieren klicken, fertig. Bei Fehlern wird der genaue Grund angezeigt (z. B. fehlender englischer Pflichtname); korrigieren und erneut hochladen. Erfordert Site-Adminrechte.",
    "plugin.guideStep4": "Auf GitHub teilen, damit andere es installieren können",
    "plugin.guideStep4Desc": "Am einfachsten: auf der GitHub-Website auf Fork klicken, den eigenen Ordner in official_plugins/ ablegen und Create pull request klicken. Alles per Mausklick im Browser, keine Werkzeuge nötig. Nach dem Merge bekommen alle das Plugin beim nächsten Update. Alternativ die .zip einfach in den Releases des eigenen Repos veröffentlichen.",
    "plugin.guideCopy": "Kopieren",
    "plugin.guideCopied": "Kopiert",
    "plugin.guideSamples": "Offizielle Plugins ansehen",
    "plugin.guidePr": "Eigenes auf GitHub einreichen",
    "plugin.guideRules": "Die drei häufigsten Stolperfallen: ① Der Ordnername muss exakt der id in plugin.json entsprechen; ② name braucht zwingend einen „en“-Eintrag (er ist der Rückfall für alle fehlenden Sprachen); ③ ein Feld-key darf nur Kleinbuchstaben, Ziffern und Unterstriche enthalten und muss mit einem Buchstaben beginnen (sichtbar ist das label — der key ist nur ein interner Name).",
