    "health.hint.missing_asset": "Der Eintrag führt einen Anhang, die eigentliche Datei liegt aber nicht mehr auf der Festplatte. Meist wurde die Datei von Hand gelöscht oder eine Sicherung ohne ihr assets-Verzeichnis zurückgespielt.",
    "health.hint.missing_embed": "Ein Bild in der Beschreibung verweist auf eine nicht vorhandene Datei und wird deshalb als defektes Bild dargestellt. Laden Sie es erneut hoch oder entfernen Sie das Bild aus dem Text.",
    "health.hint.large_asset": "Anhänge über 2 MB. Bei Bildern hilft weiter unten „Vorhandene Bildanhänge komprimieren“; große Nicht-Bilddateien sind lediglich ein Hinweis und müssen nicht angefasst werden.",
