    "srs.helpWhat": "La descrizione è nascosta e vedi solo il termine. Prova a ricordarlo, poi gira la carta per verificare. È lo sforzo di richiamo a fissare la memoria — molto più che rileggere. Se indovini, il prossimo ripasso si allontana; se sbagli, torna prima.",
    "srs.helpBoxesT": "Scatole: 1 → 3 → 7 → 14 → 30 → 90 giorni",
    "srs.helpBoxes": "Ogni termine sta in una scatola, e la scatola decide fra quanto lo rivedrai. “Ricordato” lo sposta alla scatola successiva allungando l'intervallo; “Dimenticato” lo riporta alla prima, per domani. Solo due scelte: niente arrovellarsi su quanto bene ricordavi.",
    "srs.helpZeroT": "Zero debito: {n} carte per giro, poi hai finito",
    "srs.helpZero": "Non vedrai mai “N carte in scadenza oggi”. I giorni saltati non si accumulano in un arretrato e nessun numero rosso ti insegue. Aprilo quando ti va, fai un giro e dopo {n} carte hai finito — questo archivio serve al gergo che incontri al lavoro, non a studiare all'ultimo momento.",
    "srs.helpScopeT": "Ambito: intervallo di date + modello + gruppo di parole chiave, combinabili",
    "srs.helpScope": "Un giro pesca da ciò che la barra laterale sta selezionando. Trascina la barra delle date qui sopra e ripassi solo i termini di quel periodo — quelli presi alla riunione della settimana scorsa, o il progetto ereditato il mese scorso. Il pulsante accanto sposta l'asse temporale sulla data di creazione. Scegli un modello sotto “Modelli” e un gruppo sotto “Gruppi di parole chiave” per restringere ancora: i tre si sommano. La finestra elenca l'ambito realmente attivo e offre “tutto l'archivio” quando vuoi tutto.",
    "srs.helpClose": "Ho capito",
    "srs.scopeAll": "Tutto l'archivio",
