    "admin.bkTitle": "Backup e ripristino",
    "admin.bkListTitle": "Cronologia dei backup",
    "admin.bkHint": "Backup dell'intero sito: voci, allegati, cestino e impostazioni di ogni utente, più il registro degli account e le impostazioni del sito. L'indice di ricerca e i vettori semantici, ricostruibili, non sono inclusi (vengono ricreati dopo un ripristino). Da non confondere con Importa/Esporta: quello sposta la tua libreria su un altro sito, questo è il ripristino di emergenza di questo. Le preferenze come lingua dell'interfaccia, dimensione del testo, logo/slogan e l'interruttore di compressione immagini sono salvate nel browser (localStorage), non nella cartella dati del server: non fanno quindi parte del backup — andranno reimpostate su un'altra macchina o dopo aver cancellato i dati del browser.",
