    "plugin.uninstallInUse": "⚠ {n} termini usano attualmente questo modello: dopo la disinstallazione le etichette dei campi degradano alle chiavi grezze (nessun dato va perso). Il controllo di integrità dei contenuti li elenca e può spostarli al modello predefinito con un clic.",
