    "plugin.upload": "Carica pacchetto plugin (.zip)…",
    "plugin.guideTitle": "Vuoi creare un tuo plugin? (senza programmare)",
    "plugin.guideDiyHint": "I plugin di tipo «modello di campi» sono i più facili: dati puri, senza alcun codice — un plugin.json che descrive i campi, compresso in zip e caricato. Se non va bene basta disinstallarlo: i tuoi termini restano intatti. Provane uno e manda una PR se vuoi renderlo ufficiale.",
    "plugin.guideStep1": "Prima, componi il modello di campi che vuoi nell'interfaccia",
    "plugin.guideStep1Desc": "Vai in Contenuti → Modelli di campo, imposta campi, etichette, testi guida e l'istruzione IA, poi premi “Esporta modelli”. Ottieni un .json — quel blocco è esattamente ciò che serve dopo, senza digitare nulla.",
    "plugin.guideStep2": "Crea una cartella con dentro un plugin.json",
    "plugin.guideStep2Desc": "Il nome della cartella è l'id del plugin (es. coffee-note). Copia il blocco qui sotto in plugin.json con un editor di testo, cambia id, nome e descrizione, poi incolla il modello appena esportato dentro “template”.",
    "plugin.guideStep3": "Comprimi in .zip e provalo con “Carica pacchetto” qui sotto",
    "plugin.guideStep3Desc": "Clic destro sulla cartella e comprimi. Dopo il caricamento compare nel catalogo qui sopra: premi Installa ed è attivo. Se qualcosa non va, viene indicato il motivo esatto (es. manca il nome inglese obbligatorio); correggi e ricarica. Servono i diritti di amministratore del sito.",
    "plugin.guideStep4": "Condividilo su GitHub così anche altri possono installarlo",
    "plugin.guideStep4Desc": "Il modo più semplice: sul sito GitHub premi Fork, metti la tua cartella in official_plugins/ e premi Create pull request. Tutto a clic nel browser, nessuno strumento da installare. Una volta unito, il tuo plugin arriva a tutti al prossimo aggiornamento. In alternativa pubblica lo .zip nelle Releases del tuo repository.",
    "plugin.guideCopy": "Copia",
    "plugin.guideCopied": "Copiato",
    "plugin.guideSamples": "Sfoglia i plugin ufficiali",
    "plugin.guidePr": "Invia il tuo su GitHub",
    "plugin.guideRules": "I tre punti in cui ci si blocca: ① il nome della cartella deve coincidere esattamente con l'id in plugin.json; ② name deve includere una voce “en” (è il ripiego mostrato quando manca la lingua); ③ la key di un campo può usare solo minuscole, cifre e trattini bassi e deve iniziare con una lettera (ciò che si vede è la label — la key è solo un nome interno).",
    "plugin.uploadOk": "Pacchetto caricato — plugin aggiunto al catalogo",
