    "srs.open": "Revisar",
    "srs.openTitle": "Sortear cartões de revisão do escopo filtrado atual",
    "srs.helpTitle": "O que é isto?",
    "srs.helpHeading": "Como funciona a revisão",
    "srs.helpWhatT": "Repetição espaçada: rever mesmo antes de esquecer",
    "srs.helpWhat": "A descrição fica tapada e vê apenas o termo. Tente lembrar-se e depois vire o cartão para conferir. É o esforço de evocação que fixa a memória — muito mais do que reler. Se acertar, a próxima revisão afasta-se; se falhar, volta mais cedo.",
    "srs.helpBoxesT": "Caixas: 1 → 3 → 7 → 14 → 30 → 90 dias",
    "srs.helpBoxes": "Cada termo fica numa caixa, e a caixa decide quando volta a aparecer. “Lembrei” passa-o à caixa seguinte e alarga o intervalo; “Esqueci” devolve-o à primeira caixa, para amanhã. Apenas duas opções — sem agonizar sobre quão bem se lembrou.",
    "srs.helpZeroT": "Zero dívida: {n} cartões por ronda e acabou",
    "srs.helpZero": "Nunca verá “N cartões para hoje”. Os dias saltados não se acumulam num atraso e nenhum número vermelho o persegue. Abra quando lhe apetecer, faça uma ronda e ao fim de {n} cartões terminou — este cofre é para o jargão que encontra no trabalho, não para estudar à última hora.",
    "srs.helpScopeT": "Âmbito: intervalo de datas + modelo + grupo de palavras-chave, combináveis",
    "srs.helpScope": "Uma ronda é tirada do que a barra lateral está a seleccionar. Arraste a faixa de datas acima e revê apenas os termos desse período — os apontados na reunião da semana passada, ou o projecto que assumiu no mês passado. O botão ao lado muda o eixo temporal para a data de criação. Escolha um modelo em “Modelos” e um grupo em “Grupos de palavras-chave” para afunilar; os três somam-se. A janela indica o âmbito realmente em vigor e tem “cofre inteiro” para quando quiser tudo.",
