    "admin.rlXffHint": "Os dois lados causam problema. Atrás de um proxy e com isto desligado, todos compartilham o endereço do proxy: poucas falhas bloqueiam todo mundo. Sem proxy e com isto ligado, o cabeçalho é o que o cliente quiser escrever, e um atacante troca de endereço falso a cada tentativa, contornando por completo o limite por IP (o limite por conta continua valendo).",
