    "admin.bkTitle": "Backup e restauração",
    "admin.bkListTitle": "Histórico de cópias",
    "admin.bkHint": "Backup de todo o site: entradas, anexos, lixeira e configurações de cada usuário, mais o registro de contas e as configurações do site. O índice de busca e os vetores semânticos, que são reconstruíveis, não estão incluídos (são recriados após restaurar). Não confundir com Importar/Exportar — aquilo move a sua biblioteca para outro site, isto é a recuperação de desastre deste. Preferências como idioma da interface, tamanho da fonte, texto do logo/slogan e o botão de compressão de imagens ficam no navegador (localStorage), não no diretório de dados do servidor, portanto não fazem parte do backup — será preciso configurá-las de novo em outra máquina ou após limpar os dados do navegador.",
