    "plugin.uninstallTplConfirm": "Desinstalar “{name}”? O modelo é removido da lista de modelos de campos; as notas existentes e seus valores permanecem intactos, e reinstalar restaura o modelo padrão.",
    "plugin.uninstallInUse": "⚠ {n} termos usam atualmente este modelo: após desinstalar, os rótulos dos campos passam a mostrar as chaves (nenhum dado se perde). A verificação de integridade lista-os e pode movê-los para o modelo predefinido num clique.",
