    "plugin.enhancesLabel": "Aprimora: {name}",
    "plugin.upload": "Enviar pacote de plugin (.zip)…",
    "plugin.guideTitle": "Quer criar a sua própria extensão? (sem programar)",
    "plugin.guideDiyHint": "As extensões do tipo «modelo de campos» são as fáceis: dados puros, sem qualquer código — um plugin.json a descrever os campos, comprimido em zip e carregado. Se não ficar bem, basta desinstalar; os seus termos não são afetados. Experimente criar uma e envie um PR para a tornar oficial.",
    "plugin.guideStep1": "Primeiro, monte o modelo de campos que quer na interface",
    "plugin.guideStep1Desc": "Vá a Conteúdo → Modelos de campos, defina os campos, rótulos, textos de ajuda e a instrução de IA, e clique em “Exportar modelos”. Recebe um .json — esse bloco é exatamente o que precisa a seguir, sem escrever nada.",
    "plugin.guideStep2": "Crie uma pasta com um plugin.json dentro",
    "plugin.guideStep2Desc": "O nome da pasta é o id da extensão (ex.: coffee-note). Copie o bloco abaixo para plugin.json num editor de texto, mude o id, nome e descrição, e cole o modelo que acabou de exportar em “template”.",
    "plugin.guideStep3": "Compacte em .zip e teste com “Carregar pacote” abaixo",
    "plugin.guideStep3Desc": "Clique com o botão direito na pasta e comprima. Depois de carregar, aparece no catálogo acima — clique em Instalar e está pronto. Se houver algo errado, é indicada a razão exacta (ex.: falta o nome inglês obrigatório); corrija e volte a carregar. Requer permissões de administrador do site.",
    "plugin.guideStep4": "Partilhe no GitHub para outros poderem instalar",
    "plugin.guideStep4Desc": "O caminho mais fácil: no site do GitHub clique em Fork, coloque a sua pasta em official_plugins/ e clique em Create pull request. É tudo a clicar no navegador, sem instalar ferramentas. Depois de integrada, toda a gente recebe a sua extensão na atualização seguinte. Em alternativa, publique o .zip nas Releases do seu próprio repositório.",
    "plugin.guideCopy": "Copiar",
    "plugin.guideCopied": "Copiado",
    "plugin.guideSamples": "Ver extensões oficiais",
    "plugin.guidePr": "Submeter a sua no GitHub",
    "plugin.guideRules": "Os três pontos onde as pessoas tropeçam: ① o nome da pasta tem de ser exactamente igual ao id em plugin.json; ② name tem de incluir uma entrada “en” (é o recurso mostrado quando falta o idioma); ③ a key de um campo só aceita minúsculas, dígitos e sublinhados e tem de começar por uma letra (o que se vê é o label — a key é apenas um nome interno).",
    "plugin.uploadOk": "Pacote enviado — plugin adicionado ao catálogo",
