    "tplmgr.aiPromptPh": "Instruções de conteúdo para a IA…",
    "tplmgr.builtinHint": "Os nomes dos modelos integrados são exibidos no idioma da interface enquanto permanecerem no padrão; renomeie um e seu nome personalizado será usado. Os rótulos de campos e a instrução de IA são editáveis; as chaves dos campos existentes ficam bloqueadas, mas os campos que você adicionar podem ter chave própria. “Palavra em inglês” e “Trecho de código” ficam desativados por padrão — ative-os na lista acima. Nomes e dicas dos campos seguem o idioma da interface até serem editados; depois de personalizados, sempre mostram o seu texto.",

