    "srs.helpTitle": "¿Qué es esto?",
    "srs.helpHeading": "Cómo funciona el repaso",
    "srs.helpWhatT": "Repetición espaciada: repasa justo antes de olvidar",
    "srs.helpWhat": "La descripción queda oculta y solo ves el término. Intenta recordarlo y luego gira la tarjeta para comprobar. Es el esfuerzo de recuperación lo que fija la memoria, mucho más que releer. Si aciertas, el próximo repaso se aleja; si fallas, vuelve antes.",
    "srs.helpBoxesT": "Cajas: 1 → 3 → 7 → 14 → 30 → 90 días",
    "srs.helpBoxes": "Cada término está en una caja, y la caja decide cuánto tarda en volver. «Lo recordé» lo pasa a la siguiente caja y alarga el intervalo; «Lo olvidé» lo devuelve a la primera, para mañana. Solo dos opciones: sin darle vueltas a cuánto recordabas.",
    "srs.helpZeroT": "Cero deuda: {n} tarjetas por ronda y listo",
    "srs.helpZero": "Nunca verás «N tarjetas para hoy». Los días que te saltas no se acumulan en un atraso, y ningún número rojo te persigue. Ábrelo cuando te apetezca, haz una ronda y tras {n} tarjetas has terminado: este archivo es para la jerga que te encuentras en el trabajo, no para empollar.",
    "srs.helpScopeT": "Alcance: intervalo de fechas + plantilla + grupo de palabras clave, combinables",
    "srs.helpScope": "Una ronda se saca de lo que la barra lateral tenga seleccionado. Arrastra la franja de fechas de arriba y repasarás solo los términos de ese tramo: los que anotaste en la reunión de la semana pasada, o el proyecto que asumiste el mes pasado. El botón contiguo cambia el eje temporal a la fecha de creación. Elige una plantilla en «Plantillas» y un grupo en «Grupos de palabras clave» para acotar más; los tres se suman. La ventana indica el alcance realmente vigente y ofrece «todo el archivo» cuando lo quieras todo.",
