    "admin.publicShareHint": "Desactivado por defecto. Una vez activado, cada persona puede crear enlaces públicos a sus propias notas; los enlaces son revocables en cualquier momento y toda respuesta lleva noindex, así que nunca acaba en un buscador. Desactivarlo invalida todos los enlaces existentes de inmediato.",
