    "admin.rlXffHint": "Ambas direcciones hacen daño. Tras un proxy y con esto desactivado, todos comparten la dirección del proxy: unos pocos fallos bloquean a todo el mundo. Sin proxy y con esto activado, la cabecera es lo que el cliente quiera escribir, y un atacante cambia de dirección falsa en cada intento, esquivando por completo el límite por IP (el límite por cuenta sigue vigente).",
    "admin.rlReset": "Quitar todos los bloqueos ahora",
