    "admin.bkTitle": "Copia de seguridad y restauración",
    "admin.bkListTitle": "Historial de copias",
    "admin.bkHint": "Copia de todo el sitio: entradas, adjuntos, papelera y ajustes de cada usuario, más el registro de cuentas y los ajustes del sitio. El índice de búsqueda y los vectores semánticos, reconstruibles, no se incluyen (se recrean tras restaurar). No confundir con Importar/Exportar: eso mueve tu biblioteca a otro sitio, esto es la recuperación ante desastres de este. Las preferencias como el idioma de la interfaz, el tamaño del texto, el logo/eslogan y el interruptor de compresión de imágenes se guardan en el navegador (localStorage), no en el directorio de datos del servidor, así que no forman parte de la copia — habrá que configurarlas de nuevo en otro equipo o tras borrar los datos del navegador.",
