    "plugin.guideDiyHint": "Las extensiones de tipo «plantilla de campos» son las fáciles: datos puros, sin nada de código — un plugin.json que describe los campos, comprimido en zip y subido. Si no queda bien, desinstálala; tus términos no se tocan. Anímate a crear una y envía un PR para que sea oficial.",
    "plugin.guideStep1": "Primero, monta la plantilla de campos que quieras en la interfaz",
    "plugin.guideStep1Desc": "Ve a Contenido → Plantillas de campos, configura los campos, etiquetas, textos de ayuda y la instrucción de IA, y pulsa “Exportar plantillas”. Obtendrás un .json — ese bloque es justo lo que necesitas después, sin teclear nada.",
    "plugin.guideStep2": "Crea una carpeta con un plugin.json dentro",
    "plugin.guideStep2Desc": "El nombre de la carpeta es el id de la extensión (p. ej. coffee-note). Copia el bloque de abajo en plugin.json con un editor de texto, cambia el id, el nombre y la descripción, y pega la plantilla que acabas de exportar en “template”.",
    "plugin.guideStep3": "Comprime en .zip y pruébalo con “Subir paquete” abajo",
    "plugin.guideStep3Desc": "Haz clic derecho en la carpeta y comprímela. Tras subirla aparece en el catálogo de arriba: pulsa Instalar y ya está. Si algo está mal se indica el motivo exacto (p. ej. falta el nombre en inglés obligatorio); corrígelo y vuelve a subirlo. Requiere permisos de administrador del sitio.",
    "plugin.guideStep4": "Compártela en GitHub para que otros puedan instalarla",
    "plugin.guideStep4Desc": "Lo más fácil: en la web de GitHub pulsa Fork, coloca tu carpeta en official_plugins/ y pulsa Create pull request. Todo con clics en el navegador, sin instalar herramientas. Una vez fusionada, todo el mundo recibe tu extensión en la siguiente actualización. También puedes publicar el .zip en las Releases de tu propio repositorio.",
    "plugin.guideCopy": "Copiar",
    "plugin.guideCopied": "Copiado",
    "plugin.guideSamples": "Ver extensiones oficiales",
    "plugin.guidePr": "Envía la tuya en GitHub",
    "plugin.guideRules": "Los tres puntos donde la gente se atasca: ① el nombre de la carpeta debe coincidir exactamente con el id de plugin.json; ② name debe incluir una entrada “en” (es el respaldo que se ve cuando falta el idioma); ③ la key de un campo solo admite minúsculas, dígitos y guiones bajos, y debe empezar por una letra (lo que se ve es el label — la key es solo un nombre interno).",
    "plugin.uploadOk": "Paquete subido — extensión añadida al catálogo",
    "plugin.uploadFail": "Error al subir",
    "plugin.scanErrTitle": "Estos paquetes no pasaron la validación y no se añadieron al catálogo (solo visible para administradores):",
    "plugin.deletePkg": "Eliminar paquete",
    "plugin.deletePkgConfirm": "¿Eliminar el paquete de «{name}» de este sitio? Los estados de instalación y ajustes de los usuarios se conservan; vuelve a subir un paquete con el mismo id para restaurarlo.",
    "transfer.import": "Importar…",
    "transfer.importDesc": "Lee un archivo de copia de seguridad JSON / CSV / ZIP. Los términos existentes con el mismo ID se sobrescriben.",
    "transfer.exportJson": "Exportar JSON",
    "transfer.exportJsonDesc": "Solo contenido de texto (términos, palabras clave, plantillas de campos). Las imágenes y los adjuntos no se incluyen y se romperán tras la importación.",
    "transfer.exportCsv": "Exportar CSV",
    "transfer.exportCsvDesc": "Formato de hoja de cálculo, práctico para ver o editar en lote con Excel. También sin imágenes ni adjuntos.",
    "transfer.exportZip": "Exportar ZIP (con adjuntos)",
