    "tplmgr.builtinHint": "Los nombres de las plantillas integradas se muestran en el idioma de la interfaz mientras conserven el valor predeterminado; si renombras una, se usará tu nombre personalizado. Las etiquetas de los campos y la instrucción de IA se pueden editar; las claves de los campos existentes están bloqueadas, pero los campos que añadas pueden tener su propia clave. “Palabra en inglés” y “Fragmento de código” están deshabilitadas por defecto — actívalas en la lista de arriba. Los nombres y pistas de los campos siguen el idioma de la interfaz hasta que los edites; una vez personalizados, siempre muestran tu texto.",

