    "srs.open": "복습",
    "srs.openTitle": "현재 필터 범위에서 카드를 뽑아 복습",
    "srs.helpTitle": "이게 뭔가요?",
    "srs.helpHeading": "복습은 어떻게 작동하나요",
    "srs.helpWhatT": "간격 반복: 잊기 직전에 복습하기",
    "srs.helpWhat": "설명은 가려지고 용어만 보입니다. 먼저 스스로 떠올린 뒤 카드를 뒤집어 확인하세요. 떠올리려는 행위 자체가 기억을 단단하게 만듭니다 — 다시 읽는 것보다 훨씬 효과적입니다. 맞히면 다음 복습이 뒤로 밀리고, 틀리면 더 빨리 돌아옵니다.",
    "srs.helpBoxesT": "상자: 1 → 3 → 7 → 14 → 30 → 90일",
    "srs.helpBoxes": "각 용어는 상자 하나에 들어 있고, 상자가 다음에 언제 다시 볼지를 정합니다. “기억함”은 다음 상자로 보내 간격을 늘리고, “잊음”은 첫 상자로 되돌려 내일 다시 나옵니다. 선택지는 둘뿐이라 얼마나 기억했는지 고민할 필요가 없습니다.",
    "srs.helpZeroT": "빚 없음: 한 번에 {n}장, 다 뽑으면 끝",
    "srs.helpZero": "“오늘 N장 예정” 같은 표시는 나오지 않습니다. 건너뛴 날이 밀린 숙제로 쌓이지 않고, 빨간 숫자가 쫓아오지도 않습니다. 내키면 열어서 한 번 뽑고, {n}장이면 끝입니다 — 이 저장소는 시험 벼락치기가 아니라 일터에서 마주치는 전문 용어를 위한 것입니다.",
    "srs.helpScopeT": "범위: 날짜 구간 + 템플릿 + 키워드 그룹을 함께 쓸 수 있습니다",
    "srs.helpScope": "한 번 뽑을 때는 사이드바가 지금 걸러 놓은 범위에서 뽑습니다. 위의 날짜 막대를 끌면 그 기간의 용어만 복습합니다 — 지난주 회의에서 적어 둔 것들, 지난달 넘겨받은 프로젝트처럼요. 옆의 전환 버튼으로 시간축을 생성일로 바꿀 수 있습니다. 왼쪽의 “템플릿”과 “키워드 그룹”을 함께 골라 더 좁힐 수 있고, 셋은 겹쳐서 적용됩니다. 실제로 적용된 범위는 팝업 위쪽에 표시되며, 전부 복습하려면 거기의 “저장소 전체”를 누르세요.",
