    "admin.bkListTitle": "백업 기록",
    "admin.bkHint": "사이트 전체 백업: 모든 사용자의 용어·첨부·휴지통·개별 설정에 더해 계정 등록부와 사이트 설정까지. 다시 만들 수 있는 검색 색인과 의미 벡터는 포함하지 않습니다(복원 후 자동으로 재생성). 「내보내기/가져오기」와는 다릅니다 — 그쪽은 자기 라이브러리를 다른 사이트로 옮기는 것이고, 이것은 이 사이트의 재해 복구입니다. 인터페이스 언어, 글자 크기, 로고/태그라인 문구, 이미지 압축 스위치 같은 환경설정은 브라우저(localStorage)에 저장되며 서버의 데이터 디렉터리에는 없습니다. 따라서 백업에 포함되지 않습니다 — 다른 컴퓨터에서 쓰거나 브라우저 데이터를 지우면 다시 설정해야 합니다.",
