    "plugin.uninstallTplConfirm": "“{name}”을(를) 제거할까요? 해당 템플릿은 필드 템플릿 목록에서 제거됩니다. 기존 노트와 필드 값은 그대로 유지되며, 다시 설치하면 기본 템플릿으로 복원됩니다.",
    "plugin.uninstallInUse": "⚠ 현재 {n}개 용어가 이 템플릿을 사용 중입니다. 제거 후 필드 이름이 기계 키로 표시됩니다(데이터는 사라지지 않음). 콘텐츠 상태 검사에서 목록을 보고 기본 템플릿으로 일괄 전환할 수 있습니다.",
