    "plugin.upload": "플러그인 패키지 업로드(.zip)…",
    "plugin.guideTitle": "직접 플러그인을 만들어 볼까요? (코딩 필요 없음)",
    "plugin.guideDiyHint": "「필드 템플릿」 유형의 플러그인은 비교적 쉽습니다: 코드가 전혀 없는 순수 데이터입니다 — 필드를 설명하는 plugin.json 하나를 zip으로 묶어 올리면 끝입니다. 잘못 만들었으면 제거하면 되고, 용어 데이터는 영향받지 않습니다. 직접 만들어 보시고, 공식 패키지로 넣고 싶다면 PR을 보내주세요.",
    "plugin.guideStep1": "먼저 화면에서 원하는 필드 템플릿을 만듭니다",
    "plugin.guideStep1Desc": "내용 → 필드 템플릿에서 필드·라벨·안내 문구·AI 지시를 설정한 뒤 “템플릿 내보내기”를 누르세요. .json 파일이 나오는데, 그 안의 내용이 다음 단계에서 그대로 쓰입니다. 직접 입력할 필요가 없습니다.",
    "plugin.guideStep2": "폴더를 하나 만들고 그 안에 plugin.json을 넣습니다",
    "plugin.guideStep2Desc": "폴더 이름이 곧 플러그인 id입니다(예: coffee-note). 아래 내용을 텍스트 편집기로 plugin.json에 복사한 뒤 id·이름·설명을 바꾸고, 방금 내보낸 템플릿을 “template”에 붙여 넣습니다.",
    "plugin.guideStep3": ".zip으로 압축한 뒤 아래의 “패키지 업로드”로 설치해 봅니다",
    "plugin.guideStep3Desc": "폴더를 마우스 오른쪽 버튼으로 눌러 압축하면 됩니다. 업로드하면 위 목록에 나타나고, 설치를 누르면 바로 쓸 수 있습니다. 잘못된 곳이 있으면 이유를 그대로 알려 줍니다(예: 필수인 영어 이름 누락). 고쳐서 다시 올리세요. 사이트 관리자 권한이 필요합니다.",
    "plugin.guideStep4": "GitHub에 공유해 다른 사람도 설치할 수 있게 합니다",
    "plugin.guideStep4Desc": "가장 쉬운 방법은 GitHub 웹사이트에서 Fork를 누르고, 내 폴더를 official_plugins/에 넣은 뒤 Create pull request를 누르는 것입니다. 전부 브라우저에서 클릭만 하면 되고 설치할 도구도 없습니다. 병합되면 다음 업데이트에서 모두에게 배포됩니다. 아니면 자기 저장소의 Releases에 .zip을 올려 배포해도 됩니다.",
    "plugin.guideCopy": "복사",
    "plugin.guideCopied": "복사됨",
    "plugin.guideSamples": "공식 플러그인 살펴보기",
    "plugin.guidePr": "GitHub에 내 플러그인 제출",
    "plugin.guideRules": "가장 많이 막히는 세 가지: ① 폴더 이름은 plugin.json의 id와 완전히 같아야 합니다. ② name에는 반드시 “en” 항목이 있어야 합니다(해당 언어가 없는 사람에게 표시되는 값입니다). ③ 필드 key는 소문자·숫자·밑줄만 쓸 수 있고 영문자로 시작해야 합니다(사람에게 보이는 것은 label이고 key는 내부 이름입니다).",
