    "srs.helpTitle": "Apa ini?",
    "srs.helpHeading": "Cara kerja tinjauan",
    "srs.helpWhatT": "Pengulangan berjarak: tinjau tepat sebelum lupa",
    "srs.helpWhat": "Deskripsi ditutup dan Anda hanya melihat istilahnya. Coba ingat sendiri, lalu balik kartunya untuk mencocokkan. Usaha mengingat itulah yang membuat ingatan melekat — jauh lebih ampuh daripada membaca ulang. Kalau benar, tinjauan berikutnya mundur; kalau salah, ia kembali lebih cepat.",
    "srs.helpBoxesT": "Kotak: 1 → 3 → 7 → 14 → 30 → 90 hari",
    "srs.helpBoxes": "Setiap istilah berada dalam sebuah kotak, dan kotak itu menentukan kapan ia muncul lagi. “Ingat” memindahkannya ke kotak berikutnya dan memperpanjang jeda; “Lupa” mengembalikannya ke kotak pertama untuk besok. Hanya dua pilihan — tak perlu pusing menilai seberapa ingat Anda.",
    "srs.helpZeroT": "Tanpa utang: {n} kartu per putaran, selesai",
    "srs.helpZero": "Anda tak akan pernah melihat “N kartu jatuh tempo hari ini”. Hari yang terlewat tidak menumpuk jadi tunggakan, dan tak ada angka merah yang mengejar. Buka saat ingin, tarik satu putaran, dan setelah {n} kartu selesai — brankas ini untuk istilah yang Anda temui di tempat kerja, bukan untuk sistem kebut semalam.",
    "srs.helpScopeT": "Cakupan: rentang tanggal + templat + grup kata kunci, bisa digabung",
    "srs.helpScope": "Satu putaran ditarik dari apa pun yang sedang disaring di bilah samping. Geser jalur tanggal di atas, dan Anda hanya meninjau istilah dari rentang itu — catatan rapat minggu lalu, atau proyek yang Anda ambil alih bulan lalu. Tombol di sebelahnya mengganti sumbu waktu ke tanggal pembuatan. Pilih templat di “Templat” dan grup di “Grup kata kunci” untuk mempersempit lagi; ketiganya bertumpuk. Jendela menampilkan cakupan yang benar-benar berlaku, dan menyediakan “seluruh brankas” bila Anda ingin semuanya.",
