    "admin.bkHint": "Cadangan seluruh situs: entri, lampiran, tempat sampah, dan pengaturan setiap pengguna, ditambah daftar akun dan pengaturan situs. Indeks pencarian dan vektor semantik yang bisa dibangun ulang tidak disertakan (dibuat ulang setelah pemulihan). Berbeda dengan Impor/Ekspor — itu memindahkan pustaka Anda ke situs lain, ini adalah pemulihan bencana untuk situs ini. Preferensi seperti bahasa antarmuka, ukuran huruf, teks logo/slogan, dan sakelar kompresi gambar tersimpan di peramban (localStorage), bukan di direktori data server, sehingga tidak termasuk dalam cadangan — Anda perlu mengaturnya lagi di komputer lain atau setelah membersihkan data peramban.",
