    "plugin.upload": "Unggah paket plugin (.zip)…",
    "plugin.guideTitle": "Ingin membuat plugin sendiri? (tanpa coding)",
    "plugin.guideDiyHint": "Plugin jenis «templat kolom» termasuk yang mudah: murni data, tanpa kode sama sekali — satu plugin.json yang menjelaskan kolomnya, dikompres jadi zip lalu diunggah. Kalau hasilnya kurang pas, cukup copot; data istilah Anda tidak terpengaruh. Coba buat satu, dan kirim PR kalau ingin jadi paket resmi.",
    "plugin.guideStep1": "Pertama, susun templat bidang yang Anda inginkan di antarmuka",
    "plugin.guideStep1Desc": "Buka Konten → Templat bidang, atur bidang, label, teks bantuan, dan instruksi AI, lalu tekan “Ekspor templat”. Anda mendapat berkas .json — isi itulah yang dipakai di langkah berikutnya, tanpa mengetik apa pun.",
    "plugin.guideStep2": "Buat satu folder berisi satu plugin.json",
    "plugin.guideStep2Desc": "Nama folder adalah id plugin (mis. coffee-note). Salin blok di bawah ke plugin.json dengan editor teks, ubah id, nama, dan deskripsi menjadi milik Anda, lalu tempel templat yang tadi diekspor ke dalam “template”.",
    "plugin.guideStep3": "Kompres jadi .zip dan coba lewat “Unggah paket” di bawah",
    "plugin.guideStep3Desc": "Klik kanan foldernya lalu kompres. Setelah diunggah, plugin muncul di katalog atas — tekan Pasang dan langsung bisa dipakai. Kalau ada yang salah, alasannya disebutkan langsung (mis. nama Inggris wajib tidak ada); perbaiki lalu unggah lagi. Perlu hak admin situs.",
    "plugin.guideStep4": "Bagikan di GitHub agar orang lain bisa memasangnya",
    "plugin.guideStep4Desc": "Cara termudah: di situs GitHub klik Fork, taruh folder Anda di official_plugins/, lalu klik Create pull request. Semuanya cukup klik di peramban, tanpa memasang alat apa pun. Setelah digabungkan, semua orang mendapat plugin Anda pada pembaruan berikutnya. Bisa juga cukup terbitkan .zip di Releases repositori Anda sendiri.",
    "plugin.guideCopy": "Salin",
    "plugin.guideCopied": "Tersalin",
    "plugin.guideSamples": "Lihat plugin resmi",
    "plugin.guidePr": "Kirim milik Anda di GitHub",
    "plugin.guideRules": "Tiga hal yang paling sering menghambat: ① nama folder harus persis sama dengan id di plugin.json; ② name wajib memuat entri “en” (itulah cadangan yang dilihat orang saat bahasanya tidak ada); ③ key bidang hanya boleh huruf kecil, angka, dan garis bawah, serta harus diawali huruf (yang dilihat orang adalah label — key hanya nama internal).",
