    "srs.open": "दोहराएं",
    "srs.openTitle": "मौजूदा फ़िल्टर दायरे से दोहराने के कार्ड निकालें",
    "srs.helpTitle": "यह क्या है?",
    "srs.helpHeading": "समीक्षा कैसे काम करती है",
    "srs.helpWhatT": "अंतराल पुनरावृत्ति: भूलने से ठीक पहले दोहराएँ",
    "srs.helpWhat": "विवरण छिपा रहता है और आपको केवल शब्द दिखता है। पहले खुद याद करने की कोशिश करें, फिर कार्ड पलटकर मिलाएँ। याद करने की यह कोशिश ही स्मृति को पक्का करती है — दोबारा पढ़ने से कहीं ज़्यादा। सही होने पर अगली समीक्षा आगे खिसकती है, ग़लत होने पर जल्दी लौट आती है।",
    "srs.helpBoxesT": "बॉक्स: 1 → 3 → 7 → 14 → 30 → 90 दिन",
    "srs.helpBoxes": "हर शब्द एक बॉक्स में रहता है, और बॉक्स तय करता है कि वह दोबारा कब दिखेगा। “याद था” उसे अगले बॉक्स में भेजकर अंतराल बढ़ाता है; “भूल गया” उसे पहले बॉक्स में लौटा देता है, कल के लिए। केवल दो विकल्प — कितना याद था, इस पर सोचने की ज़रूरत नहीं।",
    "srs.helpZeroT": "कोई बकाया नहीं: एक दौर में {n} कार्ड, फिर बस",
    "srs.helpZero": "यहाँ कभी “आज N कार्ड बाक़ी” नहीं दिखेगा। छूटे हुए दिन बकाया बनकर नहीं जमा होते, और कोई लाल संख्या आपका पीछा नहीं करती। मन हो तब खोलिए, एक दौर निकालिए, और {n} कार्ड के बाद बस — यह वॉल्ट परीक्षा की रटाई के लिए नहीं, काम में मिलने वाले शब्दजाल के लिए है।",
    "srs.helpScopeT": "दायरा: दिनांक सीमा + टेम्पलेट + कीवर्ड समूह, एक साथ",
    "srs.helpScope": "एक दौर उसी से निकलता है जो साइडबार अभी चुने हुए है। ऊपर की दिनांक पट्टी खींचिए और आप केवल उस अवधि के शब्द दोहराएँगे — पिछले हफ़्ते की मीटिंग में लिखे हुए, या पिछले महीने संभाला प्रोजेक्ट। बगल का बटन समय-अक्ष को निर्माण तिथि पर बदल देता है। बाईं ओर “टेम्पलेट” और “कीवर्ड समूह” चुनकर दायरा और छोटा कर सकते हैं; तीनों साथ लागू होते हैं। वास्तव में लागू दायरा पॉपअप के ऊपर दिखता है, और सब कुछ चाहिए तो वहीं “पूरा वॉल्ट” चुन लीजिए।",
    "srs.helpClose": "समझ गया",
