    "admin.rlHint": "तय समय-सीमा में विफलताएँ सीमा तक पहुँचते ही लॉगिन अस्थायी रूप से लॉक हो जाता है — सही पासवर्ड के साथ भी (वरना सही अनुमान लगते ही प्रवेश मिल जाता)। दोनों आयाम स्वतंत्र हैं: प्रति IP «एक मशीन से कई खातों पर हमला» रोकता है, प्रति खाता «कई मशीनों से एक ही खाते पर हमला» रोकता है।",
