    "admin.rlXffHint": "दोनों ही दिशाओं में नुकसान है। प्रॉक्सी के पीछे होकर इसे बंद रखने पर सबका स्रोत पता प्रॉक्सी का एक ही पता दिखेगा — कुछ विफलताएँ सबको बाहर कर देंगी। प्रॉक्सी न होने पर इसे चालू रखने पर यह हेडर क्लाइंट जो चाहे लिख सकता है, और हमलावर हर बार नकली पता बदलकर प्रति-IP सीमा को पूरी तरह चकमा दे देगा (प्रति-खाता सीमा तब भी लागू रहती है)।",
