    "admin.bkTitle": "बैकअप और पुनर्स्थापना",
    "admin.bkListTitle": "बैकअप इतिहास",
    "admin.bkHint": "पूरी साइट का बैकअप: सभी उपयोगकर्ताओं की प्रविष्टियाँ, अनुलग्नक, रीसायकल बिन और उनकी सेटिंग्स, साथ ही खाता रजिस्टर और साइट सेटिंग्स। दोबारा बनाए जा सकने वाले खोज सूचकांक और सिमैंटिक वेक्टर शामिल नहीं हैं (पुनर्स्थापना के बाद अपने आप बन जाते हैं)। यह «निर्यात/आयात» से अलग है — वह आपकी लाइब्रेरी दूसरी साइट पर ले जाता है, यह इसी साइट की आपदा-पुनर्प्राप्ति है। इंटरफ़ेस भाषा, फ़ॉन्ट आकार, लोगो/टैगलाइन टेक्स्ट और छवि-संपीड़न स्विच जैसी प्राथमिकताएँ ब्राउज़र (localStorage) में रहती हैं, सर्वर की डेटा डायरेक्टरी में नहीं — इसलिए वे बैकअप का हिस्सा नहीं हैं; दूसरी मशीन पर या ब्राउज़र डेटा साफ़ करने के बाद इन्हें दोबारा सेट करना होगा।",
    "admin.bkAuto": "स्वचालित बैकअप सक्षम करें",
    "admin.bkInterval": "हर N दिन",
    "admin.bkKeep": "N प्रतियाँ रखें",
    "admin.bkAtTime": "बैकअप का समय",
    "admin.bkAtTimeHint": "समय खाली छोड़ें तो अंतराल पूरा होते ही बैकअप हो जाएगा। समय भरने पर इसका अर्थ है \"इससे पहले नहीं\": अंतराल पूरा होने के बाद, उस समय के बाद जब कोई पहली बार साइट खोलेगा तभी बैकअप चलेगा (यहाँ जानबूझकर कोई स्थायी शेड्यूलर नहीं है)। उस दिन कोई न खोले तो अगली बार पर टल जाएगा।",
