    "plugin.uninstallTplConfirm": "“{name}” अनइंस्टॉल करें? इसका टेम्पलेट फ़ील्ड टेम्पलेट सूची से हटा दिया जाएगा; मौजूदा नोट्स और उनके फ़ील्ड मान सुरक्षित रहेंगे, और फिर से इंस्टॉल करने पर डिफ़ॉल्ट टेम्पलेट बहाल हो जाएगा।",
    "plugin.uninstallInUse": "⚠ वर्तमान में {n} शब्द इस टेम्पलेट का उपयोग कर रहे हैं: अनइंस्टॉल के बाद उनके फ़ील्ड लेबल कच्ची कुंजियों के रूप में दिखेंगे (कोई डेटा नहीं खोएगा)। कंटेंट हेल्थ जाँच उन्हें सूचीबद्ध करती है और एक क्लिक में डिफ़ॉल्ट टेम्पलेट में ले जा सकती है।",
