    "plugin.comingSoon": "इस श्रेणी के प्लगइन अभी इंस्टॉल नहीं किए जा सकते — जल्द आ रहा है",
    "plugin.enhancesLabel": "संवर्धन लक्ष्य: {name}",
    "plugin.upload": "प्लगइन पैकेज अपलोड करें (.zip)…",
    "plugin.guideTitle": "अपना प्लगइन बनाना चाहते हैं? (कोडिंग की ज़रूरत नहीं)",
    "plugin.guideDiyHint": "«फ़ील्ड टेम्पलेट» वाले प्लगइन बनाना अपेक्षाकृत आसान है: इनमें कोई कोड नहीं होता, सिर्फ़ डेटा — एक plugin.json जो फ़ील्ड बताता है, zip बनाकर अपलोड कर दीजिए। ठीक न लगे तो अनइंस्टॉल कर दें; आपके शब्दों का डेटा अछूता रहता है। एक बनाकर देखिए, और आधिकारिक पैकेज बनाना हो तो PR भेजिए।",
    "plugin.guideStep1": "पहले इंटरफ़ेस में अपनी मनचाही फ़ील्ड टेम्पलेट बनाएँ",
    "plugin.guideStep1Desc": "सामग्री → फ़ील्ड टेम्पलेट में जाकर फ़ील्ड, लेबल, संकेत-पाठ और AI निर्देश सेट करें, फिर “टेम्पलेट निर्यात करें” दबाएँ। एक .json फ़ाइल मिलेगी — उसी हिस्से की अगले चरण में ज़रूरत है, कुछ टाइप नहीं करना पड़ेगा।",
    "plugin.guideStep2": "एक फ़ोल्डर बनाएँ और उसमें एक plugin.json रखें",
    "plugin.guideStep2Desc": "फ़ोल्डर का नाम ही प्लगइन id है (जैसे coffee-note)। नीचे का हिस्सा किसी टेक्स्ट एडिटर से plugin.json में कॉपी करें, id, नाम और विवरण अपने अनुसार बदलें, फिर अभी निर्यात की गई टेम्पलेट को “template” में चिपकाएँ।",
    "plugin.guideStep3": ".zip में संपीड़ित करें और नीचे “पैकेज अपलोड करें” से आज़माएँ",
    "plugin.guideStep3Desc": "फ़ोल्डर पर राइट-क्लिक करके उसे संपीड़ित करें। अपलोड के बाद वह ऊपर की सूची में दिखेगा — इंस्टॉल दबाते ही चालू। कुछ ग़लत हुआ तो सटीक कारण बताया जाएगा (जैसे अनिवार्य अंग्रेज़ी नाम नहीं है); ठीक करके फिर अपलोड करें। साइट व्यवस्थापक अधिकार चाहिए।",
    "plugin.guideStep4": "GitHub पर साझा करें ताकि दूसरे भी इंस्टॉल कर सकें",
    "plugin.guideStep4Desc": "सबसे आसान तरीका: GitHub की वेबसाइट पर Fork दबाएँ, अपना फ़ोल्डर official_plugins/ में रखें, फिर Create pull request दबाएँ। सब कुछ ब्राउज़र में क्लिक से हो जाता है, कोई टूल इंस्टॉल नहीं करना। मर्ज होने पर अगली अपडेट में सबको आपका प्लगइन मिल जाएगा। चाहें तो अपनी ही repo की Releases में .zip प्रकाशित कर दें।",
    "plugin.guideCopy": "कॉपी",
    "plugin.guideCopied": "कॉपी हो गया",
    "plugin.guideSamples": "आधिकारिक प्लगइन देखें",
    "plugin.guidePr": "GitHub पर अपना भेजें",
    "plugin.guideRules": "तीन जगहें जहाँ लोग सबसे ज़्यादा अटकते हैं: ① फ़ोल्डर का नाम plugin.json के id से बिलकुल मेल खाना चाहिए; ② name में “en” प्रविष्टि होना अनिवार्य है (जिनकी भाषा नहीं है उन्हें यही दिखेगा); ③ फ़ील्ड की key में केवल छोटे अक्षर, अंक और अंडरस्कोर चलते हैं और शुरुआत अक्षर से होनी चाहिए (लोगों को label दिखता है, key सिर्फ़ आंतरिक नाम है)।",
    "plugin.uploadOk": "पैकेज अपलोड हो गया — प्लगइन कैटलॉग में जुड़ गया",
