const FALLBACK = "en";

function detectLang() {
  const saved = localStorage.getItem("gv-lang");
  if (saved && MESSAGES[saved]) return saved;
  const prefs = (navigator.languages && navigator.languages.length)
    ? navigator.languages : [navigator.language || ""];
  for (const l of prefs) {
    const low = (l || "").toLowerCase();
    // 中文要先分繁簡再落回預設:zh-Hans/zh-CN/zh-SG/zh-MY 是簡體,其餘 zh*
    // (zh-Hant/zh-TW/zh-HK/zh-MO,以及只寫 zh 的)一律當繁體,維持既有行為。
    if (low.startsWith("zh")) {
      return /^zh-(hans|cn|sg|my)/.test(low) ? "zh-Hans" : "zh-Hant";
    }
    if (low.startsWith("ja")) return "ja";
    if (low.startsWith("en")) return "en";
    if (low.startsWith("fr")) return "fr";
    if (low.startsWith("de")) return "de";
    if (low.startsWith("it")) return "it";
    if (low.startsWith("pt")) return "pt";
    if (low.startsWith("es")) return "es";
    if (low.startsWith("ko")) return "ko";
    if (low.startsWith("id")) return "id";
    if (low.startsWith("hi")) return "hi";
  }
  return FALLBACK;
}

export const LANG = detectLang();

// AI 生成內容的語言:localStorage 的 gv-ai-lang 覆寫,預設跟隨介面語言。
// 做成函式而不是常數:設定改了立刻生效,不用重載頁面(api.js 每次請求時呼叫)。
export function aiLang() {
  const saved = localStorage.getItem("gv-ai-lang");
  return (saved && MESSAGES[saved]) ? saved : LANG;
}

// t("key")、t("key", {n: 3}):{x} 佔位替換。缺譯時退回英文,再缺就顯示 key 本身。
export function t(key, params) {
  let s = MESSAGES[LANG][key] ?? MESSAGES[FALLBACK][key] ?? key;
  if (params) for (const [k, v] of Object.entries(params)) s = s.replaceAll(`{${k}}`, v);
  return s;
}

// 套用 index.html 的靜態文字(app.js 開機時呼叫一次):
//   data-i18n       → textContent
//   data-i18n-ph    → placeholder
//   data-i18n-title → title
export function applyI18n() {
  document.documentElement.lang = LANG;
  document.title = t("app.title");
  document.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  document.querySelectorAll("[data-i18n-title]").forEach(el => { el.title = t(el.dataset.i18nTitle); });
}
